import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 메뉴별 사용 권한 테이블이 입력 schema.sql에 없어 사용 중(사용)인 메뉴 전체를 돌려준다.
// 권한 범위 제어(공통 P1)는 공통 모듈이 맡는다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const SYSTEM_TYPES = ['ERP', '그룹웨어'];

@Controller('api/v1')
export class FnSfr00106Controller {
  @Get('/menus')
  async listMenus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const rawType = query['systemType'];
    let systemType: string | null = null;
    if (rawType !== undefined && rawType !== null && String(rawType) !== '') {
      systemType = String(rawType);
      if (!SYSTEM_TYPES.includes(systemType)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '적용 시스템 구분은 ERP 또는 그룹웨어여야 합니다.');
      }
    }
    let page = 0;
    const rawPage = query['page'];
    if (rawPage !== undefined && rawPage !== null && String(rawPage) !== '') {
      page = Number(rawPage);
      if (!Number.isInteger(page) || page < 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
      }
    }
    let size = DEFAULT_SIZE;
    const rawSize = query['size'];
    if (rawSize !== undefined && rawSize !== null && String(rawSize) !== '') {
      size = Number(rawSize);
      if (!Number.isInteger(size) || size < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
      }
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const me = await db.query(
        `SELECT employee_id FROM employee
          WHERE employee_id = CAST(:userId AS bigint)
            AND employment_status = '재직'`,
        { userId: user.id },
      );
      if (me.length === 0) {
        throw new ApiError(422, 'PERMISSION_LOOKUP_FAILED', '권한 정보를 조회하지 못했습니다.');
      }
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM menu
          WHERE use_yn = '사용'
            AND (CAST(:systemType AS varchar) IS NULL OR system_type = CAST(:systemType AS varchar))`,
        { systemType },
      );
      const items = await db.query(
        `SELECT menu_id AS "menuId",
                parent_menu_id AS "parentMenuId",
                name AS "name",
                system_type AS "systemType",
                module_link AS "moduleLink",
                sort_order AS "sortOrder"
           FROM menu
          WHERE use_yn = '사용'
            AND (CAST(:systemType AS varchar) IS NULL OR system_type = CAST(:systemType AS varchar))
          ORDER BY sort_order ASC NULLS LAST, menu_id ASC
          LIMIT :limit OFFSET :offset`,
        { systemType, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

