import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  Select,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr00106Page({ role, notify }: PageProps) {
  const [draftType, setDraftType] = useState('');
  const [systemType, setSystemType] = useState('');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const size = 20;

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/menus', role, undefined, { systemType, page, size }),
    [systemType, page, role],
  );

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  const search = () => {
    setPage(0);
    setSystemType(draftType);
  };

  const reset = () => {
    setDraftType('');
    setPage(0);
    setSystemType('');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>메뉴 현황</h2>
        <Tiles
          items={[
            ['조회된 메뉴', <Num value={total} />],
            ['현재 쪽 메뉴', <Num value={rows.length} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>업무 메뉴</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="적용 시스템 구분">
            <Select
              value={draftType}
              onChange={setDraftType}
              options={[
                ['ERP', 'ERP'],
                ['그룹웨어', '그룹웨어'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {error ? (
          <ErrorText text={error} />
        ) : (
          <>
            <Band total={total} />
            <DataTable
              columns={[
                { key: 'name', label: '메뉴명' },
                { key: 'systemType', label: '적용 시스템 구분' },
                {
                  key: 'parentMenuId',
                  label: '상위 메뉴',
                  render: (r) =>
                    r['parentMenuId'] ? (
                      <RefName table="menu" role={role} value={r['parentMenuId']} />
                    ) : (
                      <span>-</span>
                    ),
                },
                { key: 'moduleLink', label: '연결 모듈' },
                { key: 'sortOrder', label: '정렬 순서', render: (r) => <Num value={r['sortOrder']} /> },
              ]}
              rows={rows}
              onRowClick={(r) => setSelected(r)}
              empty={loading ? '불러오는 중입니다.' : '표시할 메뉴가 없습니다.'}
            />
            <Pager page={page} size={size} total={total} onPage={setPage} />
          </>
        )}
      </section>
      {selected && (
        <Drawer title="메뉴 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['메뉴명', String(selected['name'] ?? '')],
              ['적용 시스템 구분', String(selected['systemType'] ?? '')],
              [
                '상위 메뉴',
                selected['parentMenuId'] ? (
                  <RefName table="menu" role={role} value={selected['parentMenuId']} />
                ) : (
                  '-'
                ),
              ],
              ['연결 모듈', String(selected['moduleLink'] ?? '-')],
              ['정렬 순서', <Num value={selected['sortOrder']} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
